        "id": "c7c11cca-1d73-471d-9b6e-bdef51470190",
        "type": "person"
      }
    ],
    "accessible_by": [
      {
        "id": "556a1abf-4f08-40c6-878a-75890d2a88ba",
        "type": "person"
      },
      {
        "id": "1edc05f6-2702-81b5-8408-00279347f034",
